p=Path('background-effects.js');s=p.read_text(encoding='utf-8-sig');s=s.replace("[light(110,200,2,'#c3fbff'),light(600,300,6,'#c3fbff')]", "[light(110,200,2,'#c3fbff'),light(600,300,6,'#c3fbff'),effect('cascade',132,265,8,70,0,'far'),effect('cascade',620,273,8,64,4,'far')]");s=s.replace("[light(110,200,1,'#99e8df'),light(610,300,5,'#99e8df')]", "[light(110,200,1,'#99e8df'),light(610,300,5,'#99e8df'),effect('cascade',203,460,15,122,2,'far'),effect('cascade',518,460,15,122,5,'far'),effect('cascade',357,462,12,124,1,'far'),effect('cascade',357,643,18,156,6,'far')]");s=s.replace("else if(e.kind==='water'){", "else if(e.kind==='cascade'){for(let n=0;n<12;n++)pixel(x+(n%3)*p.width/4,y+((n*p.height/12+p.frame*5)%Math.max(2,p.height-8)),2,6,n%3?'#88e0e8':'#ddf8ff');}\n  else if(e.kind==='water'){");p.write_text(s,encoding='utf-8')
