p=Path('vertical-levels.test.js');s=p.read_text(encoding='utf-8-sig');s+='''\ntest('the organ crossing requires Olaf to float; front shield falls into the abyss',()=>{for(const floating of [true,false]){const s=createState(10);for(let n=0;n<60;n++)step(s,{},1/120);s.active=2;for(let n=0;n<185;n++)step(s,{right:true},1/120);for(let n=0;n<100;n++)step(s,{},1/120);if(floating)step(s,{jump:true},1/120);for(let n=0;n<480;n++)step(s,{right:true},1/120);if(floating){assert.equal(s.failed,false);assert.ok(s.heroes[2].x>850);assert.ok(s.heroes[2].y<0);}else assert.equal(s.heroes[2].dead,true);}});\n''';p.write_text(s,encoding='utf-8')
